from pathlib import Path
import base64

root = Path.cwd()
access_path = root / "lib/auth/admin-section-access.ts"
layout_path = root / "app/(portal)/admin/layout.tsx"
admin_dir = root / "app/(portal)/admin/gathering"

for required in (access_path, layout_path):
    if not required.exists():
        raise SystemExit(
            f"Could not find {required.relative_to(root)}. "
            "Run this script from the sepulchria-portal repository root."
        )

access = access_path.read_text(encoding="utf-8")
layout = layout_path.read_text(encoding="utf-8")

old_type = '  | "house_of_chances"\n  | "world";'
new_type = '  | "house_of_chances"\n  | "gathering"\n  | "world";'
if new_type not in access:
    if old_type not in access:
        raise SystemExit("Could not find AdminSection type anchor.")
    access = access.replace(old_type, new_type, 1)

old_role = '  house_of_chances: ["owner", "admin"],\n  world: ["owner", "admin", "master"],'
new_role = '  house_of_chances: ["owner", "admin"],\n  gathering: ["owner", "admin"],\n  world: ["owner", "admin", "master"],'
if new_role not in access:
    if old_role not in access:
        raise SystemExit("Could not find admin role-map anchor.")
    access = access.replace(old_role, new_role, 1)

old_nav = """            {can("house_of_chances") ? (
              <AdminNavigationLink href="/admin/house-of-chances">
                House of Chances
              </AdminNavigationLink>
            ) : null}

            {can("items") ? (
"""
new_nav = """            {can("house_of_chances") ? (
              <AdminNavigationLink href="/admin/house-of-chances">
                House of Chances
              </AdminNavigationLink>
            ) : null}

            {can("gathering") ? (
              <AdminNavigationLink href="/admin/gathering">
                Gathering
              </AdminNavigationLink>
            ) : null}

            {can("items") ? (
"""
if new_nav not in layout:
    if old_nav not in layout:
        raise SystemExit("Could not find House of Chances navigation anchor.")
    layout = layout.replace(old_nav, new_nav, 1)

access_path.write_text(access, encoding="utf-8")
layout_path.write_text(layout, encoding="utf-8")

admin_dir.mkdir(parents=True, exist_ok=True)
(admin_dir / "actions.ts").write_bytes(base64.b64decode(""))
(admin_dir / "page.tsx").write_bytes(base64.b64decode(""))

print("Gathering admin patch applied successfully.")
print("Updated:")
print(" - lib/auth/admin-section-access.ts")
print(" - app/(portal)/admin/layout.tsx")
print("Created:")
print(" - app/(portal)/admin/gathering/actions.ts")
print(" - app/(portal)/admin/gathering/page.tsx")
print()
print("Next: npm run build")
